for (const [relativePath, encoded] of Object.entries(FILES)) {
  const destination = join(PROJECT, relativePath);
  await mkdir(dirname(destination), { recursive: true });
  await writeFile(destination, Buffer.from(encoded, 'base64'));
}

const assets = [
  ['Godrays - 01.jpg', 'public/assets/godrays.jpg'],
  ['Dither Gradient - 07.png', 'public/assets/dither-gradient.png'],
];
for (const [source, relativeDestination] of assets) {
  const sourcePath = join(ROOT, source);
  try { await access(sourcePath, constants.R_OK); }
  catch { throw new Error(`Missing required visual asset: ${source}. Upload it to the repository root with this exact filename.`); }
  const destination = join(PROJECT, relativeDestination);
  await mkdir(dirname(destination), { recursive: true });
  await copyFile(sourcePath, destination);
}
console.log(`PRINT CUBE generated: ${Object.keys(FILES).length} project files plus 2 visual assets in ./print3d`);
